<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Delivery Track | EcoCycle</title><link rel="stylesheet" href="assets/css/style.css"><style>
.main{margin-left:230px;padding:105px 45px 50px;max-width:1050px}.box{background:#fff;border:1px solid #e5e5e5;border-radius:14px;padding:26px;box-shadow:0 10px 25px rgba(0,0,0,.04)}.muted{color:#687076}.list{display:grid;gap:15px;margin-top:22px}.delivery-card{border:1px solid #dce8e0;border-radius:12px;padding:18px;background:#fbfdfb}.delivery-top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.delivery-top h3{margin:0 0 5px}.status{display:inline-block;background:#eaf7ef;color:#126b37;padding:6px 10px;border-radius:20px;font-size:12px;font-weight:700;white-space:nowrap}.details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:15px}.detail{background:#f5f8f6;border-radius:8px;padding:10px}.detail small{display:block;color:#69746d;margin-bottom:4px}.empty{padding:22px;border:1px dashed #cbd8cf;border-radius:10px;color:#687076;text-align:center}@media(max-width:700px){.main{margin-left:70px;padding:95px 18px 35px}.details{grid-template-columns:1fr}.delivery-top{flex-direction:column}}
</style></head><body><?php require APP_PATH . '/views/layouts/header_sidebar.php'; ?><main class="main"><div class="box"><h2>Delivery Tracking</h2><p class="muted">See delivery assignment, delivery charge, and pickup progress here.</p><div class="list">
<?php if($loadError !== ""): ?><div class="empty">Could not load deliveries: <?php echo htmlspecialchars($loadError); ?></div>
<?php elseif(empty($deliveries)): ?><div class="empty">You do not have any delivery requests yet.</div>
<?php else: foreach($deliveries as $delivery): ?><article class="delivery-card"><div class="delivery-top"><div><h3><?php echo htmlspecialchars($delivery['item_title'] ?? 'Item'); ?></h3><span class="muted">Delivery #<?php echo (int)$delivery['delivery_id']; ?></span></div><span class="status"><?php echo htmlspecialchars($delivery['status'] ?? 'Open'); ?></span></div><div class="details"><div class="detail"><small>Delivery man</small><strong><?php echo htmlspecialchars($delivery['delivery_man_name'] ?: 'Waiting for a delivery man'); ?></strong></div><div class="detail"><small>Pickup location</small><strong><?php echo htmlspecialchars($delivery['pickup_location'] ?: 'Not provided'); ?></strong></div><div class="detail"><small>Delivery charge</small><strong><?php echo $delivery['proposed_charge'] !== null ? number_format((float)$delivery['proposed_charge'], 2) . ' BDT' : 'Not set yet'; ?></strong></div></div><?php if(($delivery['status'] ?? '')==='Charge Proposed'): ?><form method="post" action="index.php?url=delivery/charge-response" style="margin-top:14px"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>"><input type="hidden" name="delivery_id" value="<?php echo (int)$delivery['delivery_id']; ?>"><button class="status" type="submit" name="action" value="accept" style="border:0;cursor:pointer">Accept Charge</button> <button type="submit" name="action" value="reject" style="border:0;cursor:pointer;padding:6px 10px;border-radius:20px">Reject</button></form><?php endif; ?><?php if(!empty($delivery['delivery_man_phone'])): ?><p class="muted">Delivery man phone: <?php echo htmlspecialchars($delivery['delivery_man_phone']); ?></p><?php endif; ?></article><?php endforeach; endif; ?>
</div></div></main></body></html>
